        ByteIterator srcItr = sourceNode.keySequence.iterator();
        @NotNull
        ByteIterator actItr = actualNode.keySequence.iterator();
        int srcPushes = 0;
        int actPushes = 0;
        while (true) {
            if (srcItr.hasNext()) {
                if (actItr.hasNext()) {
                    if (srcItr.next() != actItr.next()) { // key is not matching
